        if (mainView.navHomeButton != null) {
            System.out.println("✅ Attempt " + attempt + ": navHomeButton found");
            // Clear any existing handlers first
            mainView.navHomeButton.setOnAction(null);
            // Set new handler
            mainView.navHomeButton.setOnAction(event -> {
