        mainView.setView(penjelasanView.getView());
    }

    private void showAnimasiPage(Teknik teknik, String olahraga) {
        AnimasiView animasiView = new AnimasiView();
        animasiView.displayAnimasi(teknik);

        animasiView.getKembaliButton().setOnAction(e -> showTeknikPage(olahraga));

        mainView.setView(animasiView.getView());
    }

    // --- Bagian Logika Kuis Tebak Gambar (10 soal) ---

    private void startTebakGambarQuiz() {
        this.daftarSoalKuis = model.getTebakGambarSoal();
        this.skorSaatIni = 0;
        this.indeksSoalSaatIni = 0;
        tampilkanSoalBerikutnya();
    }

    private void tampilkanSoalBerikutnya() {
        if (indeksSoalSaatIni >= daftarSoalKuis.size()) {
            tampilkanHasilQuiz();
            return;
        }

        Soal soal = daftarSoalKuis.get(indeksSoalSaatIni);
        QuizView quizView = new QuizView();
        quizView.displaySoal(soal);

        // Setup navbar di QuizView dengan BRUTAL FORCE
        setupNavbarForQuizView(quizView);

        for (int i = 0; i < quizView.pilihanButtons.length; i++) {
            final int jawabanPilihan = i;
            quizView.pilihanButtons[i].setOnAction(e -> {
                prosesJawaban(jawabanPilihan, soal.getJawabanBenar());
            });
        }

        quizView.getKembaliButton().setOnAction(e -> showQuizModePage());
        mainView.setView(quizView.getView());
    }

    /**
     * Setup navbar untuk QuizView dengan BRUTAL FORCE
     */
    private void setupNavbarForQuizView(QuizView quizView) {
        System.out.println(" SETUP NAVBAR FOR QUIZ VIEW");

        // Delay setup untuk memastikan UI QuizView sudah ready
        javafx.application.Platform.runLater(() -> {
            javafx.application.Platform.runLater(() -> {
                if (quizView.navHomeButton != null) {
                    System.out.println("✅ QuizView navHomeButton found");
                    quizView.navHomeButton.setOnAction(null);
                    quizView.navHomeButton.setOnAction(event -> {
                        System.out.println(" QUIZ VIEW NAVBAR HOME CLICKED!");
                        brutalNavigateToHome();
                    });
                }

                if (quizView.navMateriButton != null) {
                    System.out.println("✅ QuizView navMateriButton found");
                    quizView.navMateriButton.setOnAction(null);
                    quizView.navMateriButton.setOnAction(event -> {
                        System.out.println(" QUIZ VIEW NAVBAR MATERI CLICKED!");
                        brutalNavigateToMateri();
                    });
                }

                if (quizView.navQuizButton != null) {
                    System.out.println("✅ QuizView navQuizButton found");
                    quizView.navQuizButton.setOnAction(null);
                    quizView.navQuizButton.setOnAction(event -> {
                        System.out.println(" QUIZ VIEW NAVBAR QUIZ CLICKED!");
                        brutalNavigateToQuiz();
                    });
                }
            });
        });
    }

    private void prosesJawaban(int jawabanPilihan, int jawabanBenar) {
        if (jawabanPilihan == jawabanBenar) {
            skorSaatIni++;
        }
        indeksSoalSaatIni++;
        tampilkanSoalBerikutnya();
    }

    private void tampilkanHasilQuiz() {
        // JANGAN ganti halaman! Tampilkan overlay di atas halaman quiz-pilih mode yang sudah ada

        // Kembali ke quiz mode page dulu (jika belum ada)
        mainView.showQuizModeSelectionPage();
        attachQuizModeSelectionPageEvents();

        // Delay sedikit untuk memastikan halaman quiz mode sudah ready
        javafx.application.Platform.runLater(() -> {
            // Buat overlay hasil di atas halaman quiz mode
            HasilTebakGambarView hasilOverlay = new HasilTebakGambarView();
            hasilOverlay.displayHasil(skorSaatIni, daftarSoalKuis.size());

            // Setup button actions - tombol kembali ke quiz mode selection page
            hasilOverlay.getKembaliButton().setOnAction(e -> {
                // Tutup overlay dan kembali ke quiz mode selection page
                showQuizModeSelectionPage();
            });

            hasilOverlay.getMainLagiButton().setOnAction(e -> {
                // Tutup overlay dan mulai game lagi
                startTebakGambarQuiz();
            });

            // Setup navbar actions untuk HasilTebakGambarView
            if (hasilOverlay.getNavHomeButton() != null) {
                hasilOverlay.getNavHomeButton().setOnAction(e -> brutalNavigateToHome());
            }
            if (hasilOverlay.getNavMateriButton() != null) {
                hasilOverlay.getNavMateriButton().setOnAction(e -> brutalNavigateToMateri());
            }
            if (hasilOverlay.getNavQuizButton() != null) {
                hasilOverlay.getNavQuizButton().setOnAction(e -> brutalNavigateToQuiz());
            }

            // HasilTebakGambarView sekarang adalah popup overlay kecil, tidak ada navbar
            // Jadi tidak perlu setup navbar actions

            // TAMPILKAN OVERLAY DI ATAS HALAMAN YANG SUDAH ADA
            mainView.setView(hasilOverlay.getView());
        });
    }

    // --- Bagian Kuis Mencocokkan Gambar ---

    private void startMencocokkanGambarQuiz() {
        this.skorSaatIni = 0;
        this.currentMatchingRound = 1;
        this.matchingScore = 0;
        tampilkanMencocokkanGambarRound(1);
    }

    private void tampilkanMencocokkanGambarRound(int round) {
        if (round > 3) { // 3 rounds total
            tampilkanSkorAkhirMatching();
            return;
        }

        MatchingQuizFXView matchingView = new MatchingQuizFXView();

        // Data untuk round ini
        List<String> imagePaths, names, ids;

        switch (round) {
            case 1:
                imagePaths = Arrays.asList(
                    "/images/soccer_dribble.jpg",
                    "/images/soccer_shoot.jpg",
                    "/images/soccer_goal.jpg",
                    "/images/soccer_heading.jpg"
                );
                names = Arrays.asList("Dribbling", "Shooting", "Goal Keeping", "Heading");
                ids = Arrays.asList("dribble", "shoot", "goal", "heading");
                break;
            case 2:
                imagePaths = Arrays.asList(
                    "/images/badminton_service.jpg",
                    "/images/badminton_smash.jpg",
                    "/images/badminton_netting.jpg",
                    "/images/soccer_tackle.jpg"
                );
                names = Arrays.asList("Service", "Smash", "Netting", "Tackle");
                ids = Arrays.asList("service", "smash", "netting", "tackle");
                break;
            default:
                imagePaths = Arrays.asList(
                    "/images/soccer_goalkeeper.jpg",
                    "/images/soccer_dribble.jpg",
                    "/images/badminton_service.jpg",
                    "/images/badminton_smash.jpg"
                );
                names = Arrays.asList("Goalkeeping", "Dribble", "Badminton Service", "Badminton Smash");
                ids = Arrays.asList("goalkeeper", "dribble", "service", "smash");
                break;
        }

        List<String> shuffledNames = Arrays.asList(names.get(0), names.get(1), names.get(2), names.get(3));
        Collections.shuffle(shuffledNames);

        matchingView.setRound(round, 3, imagePaths, shuffledNames, ids);

        matchingView.setOnMatchAttempt(isCorrect -> {
            if (isCorrect) {
                matchingScore++;
            }
        });

        matchingView.setOnNextRound(() -> {
            currentMatchingRound++;
            tampilkanMencocokkanGambarRound(currentMatchingRound);
        });

        // Tambahkan callback untuk onGameComplete yang hilang
        matchingView.setOnGameComplete((correctAnswers, totalQuestions) -> {
            // Periksa nilai khusus untuk navigasi navbar
            if (correctAnswers == 0 && totalQuestions == 0) {
                // Home button clicked
                showLandingPage();
            } else if (correctAnswers == -1 && totalQuestions == -1) {
                // Materi button clicked
                showMateriPage();
            } else {
                // Normal game completion - kembali ke quiz mode (BUKAN ke hasil terpisah)
                // Karena MatchingQuizFXView sudah menampilkan hasil overlay sendiri
                showQuizModeSelectionPage();
            }
        });

        matchingView.getKembaliButton().setOnAction(e -> showQuizModePage());

        mainView.setView(matchingView.getView());
    }

    private void tampilkanSkorAkhirMatching() {
        HasilQuizView hasilView = new HasilQuizView();
        hasilView.displayHasil(matchingScore, 12); // 12 = 4 matches × 3 rounds

        hasilView.getKembaliButton().setOnAction(e -> showLandingPage());
        hasilView.getMainLagiButton().setOnAction(e -> startMencocokkanGambarQuiz());

        mainView.setView(hasilView.getView());
    }

    /**
     * Menampilkan halaman pemilihan mode quiz (Tebak Gambar vs Mencocokkan Gambar)
     */
    private void showQuizModeSelectionPage() {
        mainView.showQuizModeSelectionPage();
        // Navbar sudah di-setup sekali di constructor, tidak perlu setup ulang
        attachQuizModeSelectionPageEvents();
    }

    /**
     * Attach event handlers untuk halaman pemilihan mode quiz
     */
    private void attachQuizModeSelectionPageEvents() {

        // Event handlers untuk tombol mode quiz
        if (mainView.tebakGambarButton != null) {
            mainView.tebakGambarButton.setOnAction(e -> startTebakGambarQuiz());
        }
        if (mainView.cocokGambarButton != null) {
            mainView.cocokGambarButton.setOnAction(e -> startMencocokkanGambarQuiz());
        }
    }

    /**
     * Menampilkan halaman petunjuk
     */
    private void showInstructionsPage() {
        // Implementasi akan dibuat nanti - untuk sekarang fokus ke halaman quiz utama dulu
        System.out.println("Tombol Petunjuk ditekan - akan mengarah ke halaman petunjuk");
        // Placeholder - akan dibuat halaman petunjuk
    }
}

package com.sportedu.view;

import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.Parent;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.image.Image;
import javafx.scene.image.ImageView;
import javafx.scene.layout.*;

/**
 * View untuk menampilkan skor akhir Mencocokkan Gambar sebagai OVERLAY
 * Mirip dengan HasilTebakGambarView - background beige + navbar + overlay tipis + modal kecil
 */
public class HasilMencocokkanGambarView {

    private final BorderPane view;
    private Button mainLagiButton;
    private Button kembaliButton;

    // Navbar buttons
    public Button navHomeButton;
    public Button navMateriButton;
    public Button navQuizButton;

    public HasilMencocokkanGambarView() {
        view = new BorderPane();
        view.setPrefSize(1280, 832);

        // Tambahkan stylesheet
        view.getStylesheets().add(getClass().getResource("/styles.css").toExternalForm());
        view.getStyleClass().add("root");

        setupOverlayLayout();
    }

    private void setupOverlayLayout() {
        // Set background beige sebagai base
        view.setStyle("-fx-background-color: #F5E6A3;");

        // Background dengan dot pattern
        try {
            ImageView dotBackground = new ImageView(new Image(getClass().getResourceAsStream("/images/dot background.png")));
            dotBackground.setFitWidth(1280);
            dotBackground.setFitHeight(832);
            dotBackground.setPreserveRatio(false);

            // Container utama dengan background transparan
            BorderPane mainContainer = new BorderPane();
            mainContainer.setPrefSize(1280, 832);
            mainContainer.setStyle("-fx-background-color: transparent;");

            // Navbar di atas (tetap normal)
            HBox navbar = createNavbar();
            mainContainer.setTop(navbar);

            // Content area untuk overlay
            StackPane contentStack = new StackPane();
            contentStack.setPrefSize(1280, 752); // 832 - 80 (navbar height)
            contentStack.setStyle("-fx-background-color: transparent;");

            mainContainer.setCenter(contentStack);

            // Stack background, main container
            StackPane stackPane = new StackPane();
            stackPane.getChildren().addAll(dotBackground, mainContainer);

            view.setCenter(stackPane);

        } catch (Exception e) {
            // Fallback background beige
            view.setStyle("-fx-background-color: #F5E6A3;");

            BorderPane mainContainer = new BorderPane();
            HBox navbar = createNavbar();
            mainContainer.setTop(navbar);

            StackPane contentStack = new StackPane();
            contentStack.setPrefSize(1280, 752);
            mainContainer.setCenter(contentStack);

            view.setCenter(mainContainer);
        }
    }

    /**
     * Membuat navbar seperti halaman lain
     */
    private HBox createNavbar() {
        HBox navbar = new HBox();
        navbar.setPrefHeight(80);
        navbar.setPadding(new Insets(15, 40, 15, 40));
        navbar.setAlignment(Pos.CENTER_LEFT);
        navbar.setStyle("-fx-background-color: #516BB0;");

        // Logo SportEdu di kiri
        try {
            ImageView logo = new ImageView(new Image(getClass().getResourceAsStream("/images/logo.png")));
            logo.setFitHeight(50);
            logo.setPreserveRatio(true);

            HBox logoContainer = new HBox();
            logoContainer.setAlignment(Pos.CENTER_LEFT);
            logoContainer.getChildren().add(logo);
            navbar.getChildren().add(logoContainer);
        } catch (Exception e) {
            HBox logoContainer = new HBox();
            navbar.getChildren().add(logoContainer);
        }

        // Spacer
        HBox spacer = new HBox();
        HBox.setHgrow(spacer, javafx.scene.layout.Priority.ALWAYS);
        navbar.getChildren().add(spacer);

        // Tombol navigasi
        HBox navButtons = new HBox(30);
        navButtons.setAlignment(Pos.CENTER_RIGHT);

        navHomeButton = new Button("Halaman Utama");
        navHomeButton.setStyle("-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;");
        navHomeButton.setOnMouseEntered(e -> navHomeButton.setStyle("-fx-background-color: transparent; -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));
        navHomeButton.setOnMouseExited(e -> navHomeButton.setStyle("-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));

        navMateriButton = new Button("Materi");
        navMateriButton.setStyle("-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;");
        navMateriButton.setOnMouseEntered(e -> navMateriButton.setStyle("-fx-background-color: transparent; -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));
        navMateriButton.setOnMouseExited(e -> navMateriButton.setStyle("-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));

        navQuizButton = new Button("Quiz");
        navQuizButton.setStyle("-fx-background-color: rgba(245, 230, 163, 0.2); -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 600; -fx-border-width: 0; -fx-padding: 8 16; -fx-background-radius: 5;");

        navButtons.getChildren().addAll(navHomeButton, navMateriButton, navQuizButton);
        navbar.getChildren().add(navButtons);

        return navbar;
    }

    public void displayHasil(int skorBenar, int totalSoal) {
        // Akses content stack
        BorderPane mainContainer = (BorderPane) ((StackPane) view.getCenter()).getChildren().get(1);
        StackPane contentStack = (StackPane) mainContainer.getCenter();

        // Bersihkan content yang ada
        contentStack.getChildren().clear();

        // Overlay gelap tipis (sedikit hitam)
        VBox darkOverlay = new VBox();
        darkOverlay.setPrefSize(1280, 752);
        darkOverlay.setStyle("-fx-background-color: rgba(0, 0, 0, 0.3);");
        darkOverlay.setAlignment(Pos.CENTER);

        // Modal hasil - kotak putih kecil di tengah
        VBox modal = new VBox(25);
        modal.setAlignment(Pos.CENTER);
        modal.setPrefSize(450, 350);
        modal.setMaxSize(450, 350);
        modal.setStyle("-fx-background-color: white; -fx-background-radius: 20; -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.3), 15, 0, 0, 5);");
        modal.setPadding(new Insets(40));

        // Header dengan gambar "Skor Akhir"
        try {
            ImageView skorImage = new ImageView(new Image(getClass().getResourceAsStream("/images/Skor Akhir.png")));
            skorImage.setFitHeight(50);
            skorImage.setPreserveRatio(true);
            modal.getChildren().add(skorImage);
        } catch (Exception e) {
            Label headerLabel = new Label("Skor Akhir");
            headerLabel.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 24px; -fx-font-weight: bold; -fx-text-fill: #516BB0;");
            modal.getChildren().add(headerLabel);
        }

        // Skor
        int persentase = (int) Math.round((double) skorBenar / totalSoal * 100);

        Label skorLabel = new Label("Skor Anda:");
        skorLabel.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 18px; -fx-font-weight: 600; -fx-text-fill: #1A1E2C;");

        Label nilaiLabel = new Label(skorBenar + " / " + totalSoal + " (" + persentase + "%)");
        nilaiLabel.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 32px; -fx-font-weight: bold; -fx-text-fill: #516BB0;");

        // Pesan berdasarkan skor
        String pesanText;
        String pesanColor;
        if (persentase >= 80) {
            pesanText = "Excellent! Anda menguasai materi dengan baik!";
            pesanColor = "#2ecc71";
        } else if (persentase >= 60) {
            pesanText = "Good job! Terus tingkatkan kemampuan Anda!";
            pesanColor = "#f39c12";
        } else {
            pesanText = "Keep learning! Pelajari kembali materinya ya!";
            pesanColor = "#e74c3c";
        }

        Label pesanLabel = new Label(pesanText);
        pesanLabel.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 14px; -fx-font-weight: 500; -fx-text-fill: " + pesanColor + "; -fx-text-alignment: center;");
        pesanLabel.setWrapText(true);
        pesanLabel.setMaxWidth(350);

        modal.getChildren().addAll(skorLabel, nilaiLabel, pesanLabel);

        // Tombol aksi
        HBox buttonContainer = new HBox(15);
        buttonContainer.setAlignment(Pos.CENTER);
        buttonContainer.setPadding(new Insets(20, 0, 0, 0));

        mainLagiButton = new Button("Main Lagi");
        mainLagiButton.setPrefSize(120, 45);
        mainLagiButton.setStyle("-fx-background-color: #516BB0; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 14px; -fx-font-weight: 600; -fx-background-radius: 10;");

        kembaliButton = new Button("Kembali");
        kembaliButton.setPrefSize(120, 45);
        kembaliButton.setStyle("-fx-background-color: #F5E6A3; -fx-text-fill: #1A1E2C; -fx-font-family: 'Poppins', Arial; -fx-font-size: 14px; -fx-font-weight: 600; -fx-background-radius: 10;");

        buttonContainer.getChildren().addAll(mainLagiButton, kembaliButton);
        modal.getChildren().add(buttonContainer);

        darkOverlay.getChildren().add(modal);
        contentStack.getChildren().add(darkOverlay);
    }

    // Getter methods
    public Parent getView() {
        return view;
    }

    public Button getMainLagiButton() {
        return mainLagiButton;
    }

    public Button getKembaliButton() {
        return kembaliButton;
    }
}

package com.sportedu.view;

import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.Parent;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.image.Image;
import javafx.scene.image.ImageView;
import javafx.scene.layout.BorderPane;
import javafx.scene.layout.GridPane;
import javafx.scene.layout.HBox;
import javafx.scene.layout.VBox;

import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;

/**
 * View untuk kuis mencocokkan gambar sesuai desain "2.2 Mencocokkan Gambar.png"
 */
public class MatchingQuizFXView {

    private final BorderPane view;
    private final Label titleLabel;
    private final Label progressLabel;
    private final Label instructionLabel;
    private final GridPane gameGrid;
    private final Button kembaliButton;
    private final Button nextButton;

    private final List<Button> imageButtons = new ArrayList<>();
    private final List<Button> nameButtons = new ArrayList<>();

    private Button selectedImageButton = null;
    private Button selectedNameButton = null;
    private int correctMatches = 0;
    private Consumer<Boolean> onMatchAttempt;
    private Runnable onNextRound;

    public MatchingQuizFXView() {
        view = new BorderPane();
        view.getStyleClass().add("landing-background");
        view.setPadding(new Insets(30));

        // Header dengan progress
        VBox headerBox = new VBox(15);
        headerBox.setAlignment(Pos.CENTER);

        titleLabel = new Label("Mencocokkan Gambar");
        titleLabel.getStyleClass().add("page-title");

        progressLabel = new Label("Set 1 / 3");
        progressLabel.setStyle("-fx-font-size: 18px; -fx-text-fill: #516BB0; -fx-font-weight: 600;");

        instructionLabel = new Label("Cocokkan gambar dengan nama yang sesuai!");
        instructionLabel.setStyle("-fx-font-size: 16px; -fx-text-fill: #1A1E2C; -fx-font-weight: 500;");

        headerBox.getChildren().addAll(titleLabel, progressLabel, instructionLabel);

        // Container utama dengan background putih
        VBox contentContainer = new VBox(30);
        contentContainer.setAlignment(Pos.CENTER);
        contentContainer.setPadding(new Insets(40));
        contentContainer.getStyleClass().add("content-background");

        // Grid untuk game area
        gameGrid = new GridPane();
        gameGrid.setAlignment(Pos.CENTER);
        gameGrid.setHgap(50);
        gameGrid.setVgap(20);

        // Label untuk kolom
        Label imageColumnLabel = new Label("GAMBAR");
        imageColumnLabel.setStyle("-fx-font-size: 18px; -fx-font-weight: bold; -fx-text-fill: #516BB0;");

        Label nameColumnLabel = new Label("NAMA");
        nameColumnLabel.setStyle("-fx-font-size: 18px; -fx-font-weight: bold; -fx-text-fill: #516BB0;");

        gameGrid.add(imageColumnLabel, 0, 0);
        gameGrid.add(nameColumnLabel, 1, 0);

        // Initialize buttons untuk 4 pasangan
        for (int i = 0; i < 4; i++) {
            // Image buttons (kolom kiri)
            Button imgButton = new Button();
            imgButton.setPrefSize(180, 140);
            imgButton.getStyleClass().add("technique-card");
            imgButton.setStyle("-fx-background-color: white; -fx-border-color: #FFBC4C; -fx-border-width: 3; -fx-border-radius: 10;");
            imageButtons.add(imgButton);
            gameGrid.add(imgButton, 0, i + 1);

            // Name buttons (kolom kanan)
            Button nameButton = new Button();
            nameButton.setPrefSize(250, 60);
            nameButton.getStyleClass().add("quiz-option-button");
            nameButton.setStyle("-fx-background-color: #FEFFC4; -fx-border-color: #FFBC4C; -fx-border-width: 2; -fx-border-radius: 10; -fx-font-size: 16px; -fx-font-weight: 600;");
            nameButtons.add(nameButton);
            gameGrid.add(nameButton, 1, i + 1);
        }

        contentContainer.getChildren().add(gameGrid);

        // Control buttons
        HBox controlBox = new HBox(30);
        controlBox.setAlignment(Pos.CENTER);

        kembaliButton = UIFactory.createNavButton("/images/Back.png", 120, 50);
        nextButton = UIFactory.createPrimaryActionButton("Lanjut");
        nextButton.setDisable(true);
        nextButton.setPrefWidth(150);

        controlBox.getChildren().addAll(kembaliButton, nextButton);

        view.setTop(headerBox);
        view.setCenter(contentContainer);
        view.setBottom(controlBox);

        BorderPane.setMargin(headerBox, new Insets(0, 0, 20, 0));
        BorderPane.setMargin(controlBox, new Insets(20, 0, 0, 0));

        setupButtonEvents();
    }

    private void setupButtonEvents() {
        // Setup click events for image buttons
        for (int i = 0; i < imageButtons.size(); i++) {
            final int index = i;
            imageButtons.get(i).setOnAction(e -> selectImageButton(imageButtons.get(index)));
        }

        // Setup click events for name buttons
        for (int i = 0; i < nameButtons.size(); i++) {
            final int index = i;
            nameButtons.get(i).setOnAction(e -> selectNameButton(nameButtons.get(index)));
        }

        nextButton.setOnAction(e -> {
            if (onNextRound != null) {
                onNextRound.run();
            }
        });
    }

    private void selectImageButton(Button button) {
        if (!button.isDisabled()) {
            clearImageSelections();
            selectedImageButton = button;
            button.setStyle(button.getStyle() + "; -fx-border-color: #516BB0; -fx-border-width: 4;");
            checkMatch();
        }
    }

    private void selectNameButton(Button button) {
        if (!button.isDisabled()) {
            clearNameSelections();
            selectedNameButton = button;
            button.setStyle(button.getStyle() + "; -fx-border-color: #516BB0; -fx-border-width: 4;");
            checkMatch();
        }
    }

    private void clearImageSelections() {
        for (Button btn : imageButtons) {
            if (!btn.isDisabled()) {
                btn.setStyle("-fx-background-color: white; -fx-border-color: #FFBC4C; -fx-border-width: 3; -fx-border-radius: 10;");
            }
        }
        selectedImageButton = null;
    }

    private void clearNameSelections() {
        for (Button btn : nameButtons) {
            if (!btn.isDisabled()) {
                btn.setStyle("-fx-background-color: #FEFFC4; -fx-border-color: #FFBC4C; -fx-border-width: 2; -fx-border-radius: 10; -fx-font-size: 16px; -fx-font-weight: 600;");
            }
        }
        selectedNameButton = null;
    }

    private void checkMatch() {
        if (selectedImageButton != null && selectedNameButton != null) {
            String imageId = selectedImageButton.getId();
            String nameId = selectedNameButton.getId();

            if (imageId != null && imageId.equals(nameId)) {
                // Correct match
                markCorrect(selectedImageButton, selectedNameButton);
                correctMatches++;

                if (onMatchAttempt != null) {
                    onMatchAttempt.accept(true);
                }

                if (correctMatches >= 4) {
                    nextButton.setDisable(false);
                }
            } else {
                // Incorrect match
                markIncorrect(selectedImageButton, selectedNameButton);

                if (onMatchAttempt != null) {
                    onMatchAttempt.accept(false);
                }
            }

            selectedImageButton = null;
            selectedNameButton = null;
        }
    }

    private void markCorrect(Button imageBtn, Button nameBtn) {
        imageBtn.setDisable(true);
        nameBtn.setDisable(true);
        imageBtn.setStyle("-fx-background-color: #2ecc71; -fx-border-color: #27ae60; -fx-border-width: 4; -fx-border-radius: 10;");
        nameBtn.setStyle("-fx-background-color: #2ecc71; -fx-border-color: #27ae60; -fx-border-width: 4; -fx-border-radius: 10; -fx-text-fill: white; -fx-font-weight: bold; -fx-font-size: 16px;");
    }

    private void markIncorrect(Button imageBtn, Button nameBtn) {
        imageBtn.setStyle("-fx-background-color: #e74c3c; -fx-border-color: #c0392b; -fx-border-width: 4; -fx-border-radius: 10;");
        nameBtn.setStyle("-fx-background-color: #e74c3c; -fx-border-color: #c0392b; -fx-border-width: 4; -fx-border-radius: 10; -fx-text-fill: white; -fx-font-weight: bold; -fx-font-size: 16px;");

        // Reset after 1.5 seconds
        javafx.animation.PauseTransition pause = new javafx.animation.PauseTransition(javafx.util.Duration.seconds(1.5));
        pause.setOnFinished(e -> {
            imageBtn.setStyle("-fx-background-color: white; -fx-border-color: #FFBC4C; -fx-border-width: 3; -fx-border-radius: 10;");
            nameBtn.setStyle("-fx-background-color: #FEFFC4; -fx-border-color: #FFBC4C; -fx-border-width: 2; -fx-border-radius: 10; -fx-font-size: 16px; -fx-font-weight: 600; -fx-text-fill: black;");
        });
        pause.play();
    }

    public void setRound(int round, int totalRounds, List<String> imagePaths, List<String> names, List<String> ids) {
        progressLabel.setText("Set " + round + " / " + totalRounds);
        resetButtons();

        for (int i = 0; i < 4; i++) {
            // Set images
            try {
                Image image = new Image(getClass().getResourceAsStream(imagePaths.get(i)));
                ImageView imageView = new ImageView(image);
                imageView.setFitWidth(160);
                imageView.setFitHeight(120);
                imageView.setPreserveRatio(true);
                imageButtons.get(i).setGraphic(imageView);
                imageButtons.get(i).setText("");
                imageButtons.get(i).setId(ids.get(i));
            } catch (Exception e) {
                imageButtons.get(i).setText("Gambar\nTidak Ada");
                imageButtons.get(i).setGraphic(null);
                imageButtons.get(i).setId(ids.get(i));
            }

            // Set names
            nameButtons.get(i).setText(names.get(i));
            nameButtons.get(i).setGraphic(null);
            nameButtons.get(i).setId(ids.get(i));
        }
    }

    private void resetButtons() {
        correctMatches = 0;
        nextButton.setDisable(true);

        for (int i = 0; i < 4; i++) {
            imageButtons.get(i).setDisable(false);
            nameButtons.get(i).setDisable(false);
            imageButtons.get(i).setStyle("-fx-background-color: white; -fx-border-color: #FFBC4C; -fx-border-width: 3; -fx-border-radius: 10;");
            nameButtons.get(i).setStyle("-fx-background-color: #FEFFC4; -fx-border-color: #FFBC4C; -fx-border-width: 2; -fx-border-radius: 10; -fx-font-size: 16px; -fx-font-weight: 600;");
        }

        selectedImageButton = null;
        selectedNameButton = null;
    }

    public void setOnMatchAttempt(Consumer<Boolean> onMatchAttempt) {
        this.onMatchAttempt = onMatchAttempt;
    }

    public void setOnNextRound(Runnable onNextRound) {
        this.onNextRound = onNextRound;
    }

    public Parent getView() {
        return view;
    }

    public Button getKembaliButton() {
        return kembaliButton;
    }
}

package com.sportedu.view;

import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.Parent;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.control.ScrollPane;
import javafx.scene.image.Image;
import javafx.scene.image.ImageView;
import javafx.scene.layout.*;
import javafx.scene.paint.Color;
import javafx.scene.shape.Line;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * View untuk kuis mencocokkan gambar dengan navbar, scrolling, dan connection dots
 * Fix size 1280x832 dengan scroll jika konten lebih panjang
 */
public class MatchingQuizFXView {

    // Interface untuk callback ketika game selesai
    public interface OnGameCompleteListener {
        void onGameComplete(int correctAnswers, int totalQuestions);
    }

    // Interface untuk callback ketika match attempt
    public interface OnMatchAttemptListener {
        void onMatchAttempt(boolean isCorrect);
    }

    // Interface untuk callback ketika next round
    public interface OnNextRoundListener {
        void onNextRound();
    }

    private final BorderPane view;
    private Button kembaliButton;

    // Navbar buttons
    public Button navHomeButton;
    public Button navMateriButton;
    public Button navQuizButton;

    // Container untuk lines
    private Pane lineContainer;

    // Data untuk matching
    private List<String> imagePaths;
    private List<String> answerTexts;
    private List<String> imageIds;
    private List<String> correctAnswerIds;

    // Tracking connections
    private final Map<String, String> connections = new HashMap<>();
    private final Map<String, Button> imageButtons = new HashMap<>();
    private final Map<String, Button> answerButtons = new HashMap<>();
    private final Map<String, Line> connectionLines = new HashMap<>();

    // Line drawing
    private String selectedImageId = null;

    // Game completion callbacks
    private OnGameCompleteListener onGameComplete;
    private OnMatchAttemptListener onMatchAttempt;
    private OnNextRoundListener onNextRound;

    // Round data
    private int currentRound;
    private int totalRounds;

    public MatchingQuizFXView() {
        view = new BorderPane();
        view.setPrefSize(1280, 832);
        view.setMaxSize(1280, 832);

        // Initialize kembali button even though it won't be displayed
        kembaliButton = new Button("Kembali");
        kembaliButton.setVisible(false); // Hide it but keep it initialized

        // Tambahkan stylesheet
        try {
            view.getStylesheets().add(getClass().getResource("/styles.css").toExternalForm());
            view.getStyleClass().add("root");
        } catch (Exception e) {
            System.err.println("Could not load stylesheet: " + e.getMessage());
        }

        setupLayout();
    }

    private void setupLayout() {
        // Set background beige
        view.setStyle("-fx-background-color: #F5E6A3;");

        // Background dengan dot pattern
        try {
            ImageView dotBackground = new ImageView(new Image(getClass().getResourceAsStream("/images/dot background.png")));
            dotBackground.setFitWidth(1280);
            dotBackground.setFitHeight(832);
            dotBackground.setPreserveRatio(false);

            // Container utama
            BorderPane mainContainer = new BorderPane();
            mainContainer.setPrefSize(1280, 832);
            mainContainer.setStyle("-fx-background-color: transparent;");

            // Navbar di atas
            HBox navbar = createNavbar();
            mainContainer.setTop(navbar);

            // Content area dengan scroll
            ScrollPane scrollPane = new ScrollPane();
            scrollPane.setPrefSize(1280, 752); // 832 - 80 (navbar)
            scrollPane.setMaxSize(1280, 752);
            scrollPane.setStyle("-fx-background-color: transparent; -fx-background: transparent;");
            scrollPane.setFitToWidth(true);
            scrollPane.setHbarPolicy(ScrollPane.ScrollBarPolicy.NEVER);
            scrollPane.setVbarPolicy(ScrollPane.ScrollBarPolicy.AS_NEEDED);

            // Content container
            VBox contentContainer = createContentContainer();
            scrollPane.setContent(contentContainer);

            mainContainer.setCenter(scrollPane);

            // Stack background dan main container
            StackPane stackPane = new StackPane();
            stackPane.getChildren().addAll(dotBackground, mainContainer);

            view.setCenter(stackPane);

        } catch (Exception e) {
            // Fallback background beige
            view.setStyle("-fx-background-color: #F5E6A3;");
            System.err.println("Gagal memuat dot background: " + e.getMessage());

            // Simple layout without background image
            BorderPane mainContainer = new BorderPane();
            HBox navbar = createNavbar();
            mainContainer.setTop(navbar);

            ScrollPane scrollPane = new ScrollPane();
            scrollPane.setPrefSize(1280, 752);
            scrollPane.setStyle("-fx-background-color: transparent;");
            scrollPane.setFitToWidth(true);
            scrollPane.setHbarPolicy(ScrollPane.ScrollBarPolicy.NEVER);
            scrollPane.setVbarPolicy(ScrollPane.ScrollBarPolicy.AS_NEEDED);

            VBox contentContainer = createContentContainer();
            scrollPane.setContent(contentContainer);
            mainContainer.setCenter(scrollPane);

            view.setCenter(mainContainer);
        }
    }

    private VBox createContentContainer() {
        VBox container = new VBox(40);
        container.setAlignment(Pos.TOP_CENTER);
        container.setPadding(new Insets(40, 50, 40, 50));
        container.setStyle("-fx-background-color: transparent;");
        container.setMinHeight(800); // Minimum height untuk memastikan scroll berfungsi

        // Header dengan gambar "Cocokkan Gambar"
        VBox headerSection = new VBox(30);
        headerSection.setAlignment(Pos.CENTER);

        try {
            ImageView headerImage = new ImageView(new Image(getClass().getResourceAsStream("/images/Cocokkan Gambar.png")));
            headerImage.setFitHeight(80);
            headerImage.setPreserveRatio(true);
            headerSection.getChildren().add(headerImage);
        } catch (Exception e) {
            Label headerLabel = new Label("Mencocokkan Gambar");
            headerLabel.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 28px; -fx-font-weight: bold; -fx-text-fill: #516BB0;");
            headerSection.getChildren().add(headerLabel);
        }

        // Instruksi dengan warna biru dan tebal
        Label instruksiLabel = new Label("Hubungkan gambar dengan jawaban yang tepat dengan menarik garis dari titik ke titik");
        instruksiLabel.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: bold; -fx-text-fill: #516BB0; -fx-text-alignment: center;");
        instruksiLabel.setWrapText(true);
        instruksiLabel.setMaxWidth(600);
        headerSection.getChildren().add(instruksiLabel);

        container.getChildren().add(headerSection);
        return container;
    }

    /**
     * Setup matching game dengan data gambar dan jawaban
     */
    public void setupMatchingGame(List<String> imagePaths, List<String> answerTexts, List<String> imageIds, List<String> correctAnswerIds) {
        this.imagePaths = imagePaths;
        this.answerTexts = answerTexts;
        this.imageIds = imageIds;
        this.correctAnswerIds = correctAnswerIds;

        // Clear previous connections
        connections.clear();
        imageButtons.clear();
        answerButtons.clear();
        connectionLines.clear();

        // Get content container
        VBox contentContainer = (VBox) ((ScrollPane) ((BorderPane) ((StackPane) view.getCenter()).getChildren().get(1)).getCenter()).getContent();

        // Clear previous game content (keep header)
        if (contentContainer.getChildren().size() > 1) {
            contentContainer.getChildren().subList(1, contentContainer.getChildren().size()).clear();
        }

        // Game area dengan line container
        StackPane gameArea = new StackPane();
        gameArea.setPrefHeight(600);
        gameArea.setMaxHeight(600);

        // Line container untuk menggambar garis (di layer paling atas)
        lineContainer = new Pane();
        lineContainer.setPrefSize(1180, 600);
        lineContainer.setStyle("-fx-background-color: transparent;");
        lineContainer.setMouseTransparent(true); // Allow clicks to pass through

        // Main game layout
        HBox gameLayout = new HBox(150); // Space between columns
        gameLayout.setAlignment(Pos.CENTER);
        gameLayout.setPadding(new Insets(50));

        // Left side - Images
        VBox imageColumn = createImageColumn();

        // Right side - Answers
        VBox answerColumn = createAnswerColumn();

        gameLayout.getChildren().addAll(imageColumn, answerColumn);

        // Add game layout first, then line container on top
        gameArea.getChildren().addAll(gameLayout, lineContainer);

        contentContainer.getChildren().add(gameArea);

        // No buttons section - removed completely
    }

    private VBox createImageColumn() {
        VBox imageColumn = new VBox(40);
        imageColumn.setAlignment(Pos.CENTER_LEFT);
        imageColumn.setPrefWidth(450);

        // Remove subtitle - no "Gambar" label

        for (int i = 0; i < imagePaths.size(); i++) {
            HBox imageRow = createImageRow(imagePaths.get(i), imageIds.get(i), i);
            imageColumn.getChildren().add(imageRow);
        }

        return imageColumn;
    }

    private HBox createImageRow(String imagePath, String imageId, int index) {
        HBox row = new HBox(20);
        row.setAlignment(Pos.CENTER_LEFT);

        // Image container with light beige background that matches the dot color scheme
        VBox imageContainer = new VBox();
        imageContainer.setAlignment(Pos.CENTER);
        imageContainer.setStyle("-fx-background-color: #F5E6A3; -fx-background-radius: 15; -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.3), 10, 0, 0, 4); -fx-padding: 8;");

        try {
            ImageView imageView = new ImageView(new Image(getClass().getResourceAsStream(imagePath)));
            // Let image maintain its natural proportions
            imageView.setPreserveRatio(true);

            // Get image natural size and adapt container
            Image img = imageView.getImage();
            double imgWidth = img.getWidth();
            double imgHeight = img.getHeight();

            // Scale to fit within max bounds while preserving ratio
            double maxWidth = 180;
            double maxHeight = 110;
            double scaleX = maxWidth / imgWidth;
            double scaleY = maxHeight / imgHeight;
            double scale = Math.min(scaleX, scaleY);

            double finalWidth = imgWidth * scale;
            double finalHeight = imgHeight * scale;

            imageView.setFitWidth(finalWidth);
            imageView.setFitHeight(finalHeight);

            // Container adapts to actual image size plus padding (stroke effect)
            imageContainer.getChildren().add(imageView);
            imageContainer.setPrefSize(finalWidth + 16, finalHeight + 16); // 8px padding on each side

        } catch (Exception e) {
            Label placeholder = new Label("Gambar " + (index + 1));
            placeholder.setStyle("-fx-font-size: 16px; -fx-text-fill: #666;");
            imageContainer.getChildren().add(placeholder);
            imageContainer.setPrefSize(196, 126); // Default size with padding
        }

        // Larger connection point (dot)
        Button connectPoint = new Button();
        connectPoint.setPrefSize(35, 35);
        connectPoint.setStyle("-fx-background-color: transparent; -fx-border-width: 0; -fx-padding: 0;");

        try {
            ImageView dotIcon = new ImageView(new Image(getClass().getResourceAsStream("/images/Cocokkan gambar titik.png")));
            dotIcon.setFitWidth(30);
            dotIcon.setFitHeight(30);
            dotIcon.setPreserveRatio(true);
            connectPoint.setGraphic(dotIcon);
        } catch (Exception e) {
            // Fallback: larger colored circle
            connectPoint.setStyle("-fx-background-color: #516BB0; -fx-background-radius: 17; -fx-border-width: 0;");
        }

        connectPoint.setOnAction(e -> startConnection(imageId, connectPoint));

        imageButtons.put(imageId, connectPoint);
        row.getChildren().addAll(imageContainer, connectPoint);
        return row;
    }

    private VBox createAnswerColumn() {
        VBox answerColumn = new VBox(40);
        answerColumn.setAlignment(Pos.CENTER_RIGHT);
        answerColumn.setPrefWidth(450);

        // Remove subtitle - no "Jawaban" label

        for (int i = 0; i < answerTexts.size(); i++) {
            HBox answerRow = createAnswerRow(answerTexts.get(i), imageIds.get(i));
            answerColumn.getChildren().add(answerRow);
        }

        return answerColumn;
    }

    private HBox createAnswerRow(String answerText, String answerId) {
        HBox row = new HBox(20);
        row.setAlignment(Pos.CENTER_RIGHT);

        // Larger connection point (dot)
        Button connectPoint = new Button();
        connectPoint.setPrefSize(35, 35);
        connectPoint.setStyle("-fx-background-color: transparent; -fx-border-width: 0; -fx-padding: 0;");

        try {
            ImageView dotIcon = new ImageView(new Image(getClass().getResourceAsStream("/images/Cocokkan gambar titik.png")));
            dotIcon.setFitWidth(30);
            dotIcon.setFitHeight(30);
            dotIcon.setPreserveRatio(true);
            connectPoint.setGraphic(dotIcon);
        } catch (Exception e) {
            // Fallback: larger colored circle
            connectPoint.setStyle("-fx-background-color: #F5E6A3; -fx-background-radius: 17; -fx-border-width: 0;");
        }

        connectPoint.setOnAction(e -> completeConnection(answerId, connectPoint));

        // Answer container with light beige background matching the dots
        VBox answerContainer = new VBox();
        answerContainer.setAlignment(Pos.CENTER);
        answerContainer.setPrefSize(200, 130);
        answerContainer.setStyle("-fx-background-color: #F5E6A3; -fx-background-radius: 15; -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.3), 10, 0, 0, 4); -fx-padding: 10;");

        // Answer label with blue text, bolder and perfectly centered
        Label answerLabel = new Label(answerText);
        answerLabel.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 900; -fx-text-fill: #516BB0; -fx-text-alignment: center;");
        answerLabel.setWrapText(true);
        answerLabel.setMaxWidth(180);
        answerLabel.setAlignment(Pos.CENTER);
        VBox.setVgrow(answerLabel, Priority.ALWAYS);
        answerContainer.getChildren().add(answerLabel);

        answerButtons.put(answerId, connectPoint);
        row.getChildren().addAll(connectPoint, answerContainer);
        return row;
    }

    private void startConnection(String imageId, Button imageButton) {
        // Clear previous selection
        resetAllButtonStyles();

        selectedImageId = imageId;

        // Visual feedback - highlight selected image point
        try {
            ImageView selectedDot = new ImageView(new Image(getClass().getResourceAsStream("/images/Cocokkan gambar titik.png")));
            selectedDot.setFitWidth(20);
            selectedDot.setFitHeight(20);
            selectedDot.setPreserveRatio(true);
            selectedDot.setStyle("-fx-effect: dropshadow(gaussian, #2ecc71, 10, 0, 0, 0);");
            imageButton.setGraphic(selectedDot);
        } catch (Exception e) {
            imageButton.setStyle("-fx-background-color: #2ecc71; -fx-background-radius: 12; -fx-border-width: 0;");
        }

        // If there was a previous connection from this image, highlight the connected answer
        String connectedAnswerId = connections.get(imageId);
        if (connectedAnswerId != null) {
            Button answerButton = answerButtons.get(connectedAnswerId);
            try {
                ImageView connectedDot = new ImageView(new Image(getClass().getResourceAsStream("/images/Cocokkan gambar titik.png")));
                connectedDot.setFitWidth(20);
                connectedDot.setFitHeight(20);
                connectedDot.setPreserveRatio(true);
                connectedDot.setStyle("-fx-effect: dropshadow(gaussian, #e74c3c, 10, 0, 0, 0);");
                answerButton.setGraphic(connectedDot);
            } catch (Exception e) {
                answerButton.setStyle("-fx-background-color: #e74c3c; -fx-background-radius: 12; -fx-border-width: 0;");
            }
        }
    }

    private void completeConnection(String answerId, Button answerButton) {
        if (selectedImageId != null) {
            // Remove old connection if exists
            String oldAnswer = connections.get(selectedImageId);
            if (oldAnswer != null) {
                Line oldLine = connectionLines.get(selectedImageId);
                if (oldLine != null) {
                    lineContainer.getChildren().remove(oldLine);
                }
            }

            // Create new connection
            Button imageButton = imageButtons.get(selectedImageId);
            Line line = createConnectionLine(imageButton, answerButton);

            // All lines are blue regardless of correctness
            line.setStroke(Color.web("#516BB0")); // Blue for all connections

            lineContainer.getChildren().add(line);
            connections.put(selectedImageId, answerId);
            connectionLines.put(selectedImageId, line);

            // Check if answer is correct for scoring
            boolean isCorrect = false;
            for (int i = 0; i < imageIds.size(); i++) {
                if (imageIds.get(i).equals(selectedImageId) && correctAnswerIds.get(i).equals(answerId)) {
                    isCorrect = true;
                    break;
                }
            }

            // Notify match attempt
            if (onMatchAttempt != null) {
                onMatchAttempt.onMatchAttempt(isCorrect);
            }

            // Reset visual feedback
            resetAllButtonStyles();
            selectedImageId = null;

            // Check if all connections are made
            checkAllConnectionsComplete();
        }
    }

    private Line createConnectionLine(Button startButton, Button endButton) {
        Line line = new Line();

        // Use layout bounds in scene for more accurate positioning
        javafx.geometry.Bounds startBounds = startButton.localToScene(startButton.getBoundsInLocal());
        javafx.geometry.Bounds endBounds = endButton.localToScene(endButton.getBoundsInLocal());
        javafx.geometry.Bounds containerBounds = lineContainer.localToScene(lineContainer.getBoundsInLocal());

        // Calculate center points relative to line container
        double startX = startBounds.getCenterX() - containerBounds.getMinX();
        double startY = startBounds.getCenterY() - containerBounds.getMinY();
        double endX = endBounds.getCenterX() - containerBounds.getMinX();
        double endY = endBounds.getCenterY() - containerBounds.getMinY();

        line.setStartX(startX);
        line.setStartY(startY);
        line.setEndX(endX);
        line.setEndY(endY);

        line.setStrokeWidth(4);
        line.setOpacity(0.9);

        return line;
    }

    private void checkAllConnectionsComplete() {
        // Check if all images have connections
        if (connections.size() == imageIds.size()) {
            // All connections made - always show results first
            javafx.application.Platform.runLater(() -> {
                try {
                    Thread.sleep(1000); // Brief pause to show all lines
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }

                // Always show results when all connections are complete
                checkAnswers();
            });
        }
    }

    private void resetAllButtonStyles() {
        // Reset image buttons
        for (Button button : imageButtons.values()) {
            try {
                ImageView normalDot = new ImageView(new Image(getClass().getResourceAsStream("/images/Cocokkan gambar titik.png")));
                normalDot.setFitWidth(30);
                normalDot.setFitHeight(30);
                normalDot.setPreserveRatio(true);
                button.setGraphic(normalDot);
            } catch (Exception e) {
                button.setStyle("-fx-background-color: #516BB0; -fx-background-radius: 17; -fx-border-width: 0;");
            }
        }

        // Reset answer buttons
        for (Button button : answerButtons.values()) {
            try {
                ImageView normalDot = new ImageView(new Image(getClass().getResourceAsStream("/images/Cocokkan gambar titik.png")));
                normalDot.setFitWidth(30);
                normalDot.setFitHeight(30);
                normalDot.setPreserveRatio(true);
                button.setGraphic(normalDot);
            } catch (Exception e) {
                button.setStyle("-fx-background-color: #F5E6A3; -fx-background-radius: 17; -fx-border-width: 0;");
            }
        }
    }

    private void checkAnswers() {
        // Calculate score
        int correctCount = 0;
        for (int i = 0; i < imageIds.size(); i++) {
            String imageId = imageIds.get(i);
            String userAnswer = connections.get(imageId);
            String correctAnswer = correctAnswerIds.get(i);

            if (userAnswer != null && userAnswer.equals(correctAnswer)) {
                correctCount++;
            }
        }

        // Show compact result display
        showCompactResults(correctCount, imageIds.size());
    }

    /**
     * Display compact results following guess image quiz concept
     */
    public void showCompactResults(int correctAnswers, int totalQuestions) {
        // Create semi-transparent overlay
        StackPane overlay = new StackPane();
        overlay.setStyle("-fx-background-color: rgba(0, 0, 0, 0.5);");
        overlay.setPrefSize(1280, 832);

        // Very compact result container matching the reference design
        VBox resultContainer = new VBox(15);
        resultContainer.setAlignment(Pos.CENTER);
        resultContainer.setPrefSize(300, 240);  // Sedikit diperbesar untuk tombol yang lebih besar
        resultContainer.setMaxSize(300, 240);
        resultContainer.setStyle("-fx-background-color: white; -fx-background-radius: 12; -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.2), 8, 0, 0, 2); -fx-padding: 20;");

        // Skor Akhir image header - ukuran tetap kecil
        try {
            ImageView scoreImage = new ImageView(new Image(getClass().getResourceAsStream("/images/Skor Akhir.png")));
            scoreImage.setFitHeight(35);
            scoreImage.setPreserveRatio(true);
            resultContainer.getChildren().add(scoreImage);
        } catch (Exception e) {
            Label scoreLabel = new Label("Skor Akhir");
            scoreLabel.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: bold; -fx-text-fill: #516BB0;");
            resultContainer.getChildren().add(scoreLabel);
        }

        // Score display
        Label scoreText = new Label(correctAnswers + "/" + totalQuestions);
        scoreText.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 32px; -fx-font-weight: bold; -fx-text-fill: #2C5F2D;");
        resultContainer.getChildren().add(scoreText);

        // Percentage
        int percentage = (int) Math.round((double) correctAnswers / totalQuestions * 100);
        Label percentageLabel = new Label(percentage + "%");
        percentageLabel.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 24px; -fx-font-weight: bold; -fx-text-fill: #2C5F2D;");
        resultContainer.getChildren().add(percentageLabel);

        // Single yellow back button using Kembali_kuning.png - ukuran diperbesar lagi
        Button backButton = new Button();
        backButton.setPrefSize(180, 60);  // Diperbesar lagi dari 140x50 menjadi 180x60
        backButton.setStyle("-fx-background-color: transparent; -fx-border-width: 0; -fx-padding: 0; -fx-cursor: hand;");

        try {
            ImageView backIcon = new ImageView(new Image(getClass().getResourceAsStream("/images/Kembali_kuning.png")));
            backIcon.setFitWidth(180);  // Sesuaikan dengan ukuran button
            backIcon.setFitHeight(60);
            backIcon.setPreserveRatio(true);
            backButton.setGraphic(backIcon);
        } catch (Exception e) {
            // Fallback button with yellow styling
            backButton.setText("Kembali");
            backButton.setStyle("-fx-background-color: #F5E6A3; -fx-background-radius: 25; -fx-text-fill: #516BB0; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: bold; -fx-cursor: hand;");
        }

        // Perbaiki action handler untuk memastikan tombol bekerja
        backButton.setOnAction(e -> {
            System.out.println("Back button clicked!"); // Debug log

            // Remove overlay first
            StackPane mainStack = (StackPane) view.getCenter();
            mainStack.getChildren().remove(overlay);

            // Then call the completion handler
            if (onGameComplete != null) {
                onGameComplete.onGameComplete(correctAnswers, totalQuestions);
            } else {
                System.out.println("onGameComplete is null!"); // Debug log
            }
        });

        // Tambahkan hover effect untuk memastikan tombol responsif
        backButton.setOnMouseEntered(e -> {
            backButton.setStyle(backButton.getStyle() + "; -fx-opacity: 0.8;");
        });

        backButton.setOnMouseExited(e -> {
            backButton.setStyle(backButton.getStyle().replace("; -fx-opacity: 0.8;", ""));
        });

        resultContainer.getChildren().add(backButton);

        overlay.getChildren().add(resultContainer);

        // Add overlay to main view
        StackPane mainStack = (StackPane) view.getCenter();
        mainStack.getChildren().add(overlay);
    }

    /**
     * Membuat navbar dengan logo dan tombol navigasi
     */
    private HBox createNavbar() {
        HBox navbar = new HBox();
        navbar.setPrefHeight(80);
        navbar.setPadding(new Insets(15, 40, 15, 40));
        navbar.setAlignment(Pos.CENTER_LEFT);
        navbar.setStyle("-fx-background-color: #516BB0;");

        // Logo SportEdu di kiri
        try {
            ImageView logo = new ImageView(new Image(getClass().getResourceAsStream("/images/logo.png")));
            logo.setFitHeight(50);
            logo.setPreserveRatio(true);

            HBox logoContainer = new HBox();
            logoContainer.setAlignment(Pos.CENTER_LEFT);
            logoContainer.getChildren().add(logo);
            navbar.getChildren().add(logoContainer);
        } catch (Exception e) {
            HBox logoContainer = new HBox();
            Label logoText = new Label("SportEdu");
            logoText.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 24px; -fx-font-weight: bold; -fx-text-fill: white;");
            logoContainer.getChildren().add(logoText);
            navbar.getChildren().add(logoContainer);
        }

        // Spacer
        HBox spacer = new HBox();
        HBox.setHgrow(spacer, javafx.scene.layout.Priority.ALWAYS);
        navbar.getChildren().add(spacer);

        // Tombol navigasi
        HBox navButtons = new HBox(30);
        navButtons.setAlignment(Pos.CENTER_RIGHT);

        navHomeButton = new Button("Halaman Utama");
        navHomeButton.setStyle("-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16; -fx-cursor: hand;");
        navHomeButton.setOnMouseEntered(e -> navHomeButton.setStyle("-fx-background-color: transparent; -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16; -fx-cursor: hand;"));
        navHomeButton.setOnMouseExited(e -> navHomeButton.setStyle("-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16; -fx-cursor: hand;"));
        // Perbaiki action handler untuk tombol Home dengan debug
        navHomeButton.setOnAction(e -> {
            System.out.println(" NAVBAR HOME CLICKED in MatchingQuizFXView!");
            System.out.println("onGameComplete is null? " + (onGameComplete == null));
            if (onGameComplete != null) {
                System.out.println("Calling onGameComplete(0, 0) for Home navigation");
                onGameComplete.onGameComplete(0, 0); // Dummy values for navigation
            } else {
                System.out.println("❌ ERROR: onGameComplete is NULL! Cannot navigate to Home!");
            }
        });

        navMateriButton = new Button("Materi");
        navMateriButton.setStyle("-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16; -fx-cursor: hand;");
        navMateriButton.setOnMouseEntered(e -> navMateriButton.setStyle("-fx-background-color: transparent; -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16; -fx-cursor: hand;"));
        navMateriButton.setOnMouseExited(e -> navMateriButton.setStyle("-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16; -fx-cursor: hand;"));
        // Perbaiki action handler untuk tombol Materi dengan debug
        navMateriButton.setOnAction(e -> {
            System.out.println(" NAVBAR MATERI CLICKED in MatchingQuizFXView!");
            System.out.println("onGameComplete is null? " + (onGameComplete == null));
            if (onGameComplete != null) {
                System.out.println("Calling onGameComplete(-1, -1) for Materi navigation");
                onGameComplete.onGameComplete(-1, -1); // Special values to indicate Materi navigation
            } else {
                System.out.println("❌ ERROR: onGameComplete is NULL! Cannot navigate to Materi!");
            }
        });

        navQuizButton = new Button("Quiz");
        navQuizButton.setStyle("-fx-background-color: rgba(245, 230, 163, 0.2); -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 600; -fx-border-width: 0; -fx-padding: 8 16; -fx-background-radius: 5; -fx-cursor: hand;");
        // Quiz button is current page, so no action needed but add hover for consistency
        navQuizButton.setOnMouseEntered(e -> navQuizButton.setStyle("-fx-background-color: rgba(245, 230, 163, 0.3); -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 600; -fx-border-width: 0; -fx-padding: 8 16; -fx-background-radius: 5; -fx-cursor: hand;"));
        navQuizButton.setOnMouseExited(e -> navQuizButton.setStyle("-fx-background-color: rgba(245, 230, 163, 0.2); -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 600; -fx-border-width: 0; -fx-padding: 8 16; -fx-background-radius: 5; -fx-cursor: hand;"));
        // Quiz button action with debug
        navQuizButton.setOnAction(e -> {
            System.out.println(" NAVBAR QUIZ CLICKED in MatchingQuizFXView!");
            System.out.println("Already on Quiz page - no navigation needed");
        });

        navButtons.getChildren().addAll(navHomeButton, navMateriButton, navQuizButton);
        navbar.getChildren().add(navButtons);

        return navbar;
    }

    // Getter methods
    public Parent getView() {
        return view;
    }

    public Button getKembaliButton() {
        return kembaliButton;
    }

    public void setOnGameComplete(OnGameCompleteListener listener) {
        this.onGameComplete = listener;
    }

    // Methods expected by MainPresenter
    public void setRound(int round, int totalRounds, List<String> imagePaths, List<String> answerTexts, List<String> imageIds) {
        this.currentRound = round;
        this.totalRounds = totalRounds;

        // Use the first 4 images as correct answers (same order)
        List<String> correctIds = new ArrayList<>(imageIds);

        setupMatchingGame(imagePaths, answerTexts, imageIds, correctIds);
    }

    public void setOnMatchAttempt(OnMatchAttemptListener listener) {
        this.onMatchAttempt = listener;
    }

    public void setOnNextRound(OnNextRoundListener listener) {
        this.onNextRound = listener;
    }
}

package com.sportedu.view;

import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.Parent;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.control.ScrollPane;
import javafx.scene.image.Image;
import javafx.scene.image.ImageView;
import javafx.scene.layout.*;
import javafx.scene.paint.Color;
import javafx.scene.shape.Line;
import javafx.scene.Node;
import java.util.List;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.Map;

/**
 * View untuk halaman mencocokkan gambar dengan fitur drag-and-drop
 * Fix size 1280x832 dengan scroll jika konten lebih panjang
 */
public class MencocokkanGambarView {

    // Interface untuk callback ketika game selesai
    public interface OnGameCompleteListener {
        void onGameComplete(int correctAnswers, int totalQuestions);
    }

    private final BorderPane view;
    private Button kembaliButton;

    // Navbar buttons
    public Button navHomeButton;
    public Button navMateriButton;
    public Button navQuizButton;

    // Container untuk lines
    private Pane lineContainer;

    // Data untuk matching
    private List<String> imagePaths;
    private List<String> answerTexts;
    private List<String> imageIds;
    private List<String> correctAnswerIds; // ID jawaban yang benar untuk setiap gambar

    // Tracking connections
    private Map<String, String> connections = new HashMap<>();
    private Map<String, Button> imageButtons = new HashMap<>();
    private Map<String, Button> answerButtons = new HashMap<>();
    private Map<String, Line> connectionLines = new HashMap<>();

    // Line drawing
    private Line currentLine = null;
    private String selectedImageId = null;

    // Game completion callback
    private OnGameCompleteListener onGameComplete;

    public MencocokkanGambarView() {
        view = new BorderPane();
        view.setPrefSize(1280, 832);
        view.setMaxSize(1280, 832);

        // Tambahkan stylesheet
        view.getStylesheets().add(getClass().getResource("/styles.css").toExternalForm());
        view.getStyleClass().add("root");

        setupLayout();
    }

    private void setupLayout() {
        // Set background beige
        view.setStyle("-fx-background-color: #F5E6A3;");

        // Background dengan dot pattern
        try {
            ImageView dotBackground = new ImageView(new Image(getClass().getResourceAsStream("/images/dot background.png")));
            dotBackground.setFitWidth(1280);
            dotBackground.setFitHeight(832);
            dotBackground.setPreserveRatio(false);

            // Container utama
            BorderPane mainContainer = new BorderPane();
            mainContainer.setPrefSize(1280, 832);
            mainContainer.setStyle("-fx-background-color: transparent;");

            // Navbar di atas
            HBox navbar = createNavbar();
            mainContainer.setTop(navbar);

            // Content area dengan scroll
            ScrollPane scrollPane = new ScrollPane();
            scrollPane.setPrefSize(1280, 752); // 832 - 80 (navbar)
            scrollPane.setMaxSize(1280, 752);
            scrollPane.setStyle("-fx-background-color: transparent; -fx-background: transparent;");
            scrollPane.setFitToWidth(true);
            scrollPane.setHbarPolicy(ScrollPane.ScrollBarPolicy.NEVER);
            scrollPane.setVbarPolicy(ScrollPane.ScrollBarPolicy.AS_NEEDED);

            // Content container
            VBox contentContainer = createContentContainer();
            scrollPane.setContent(contentContainer);

            mainContainer.setCenter(scrollPane);

            // Stack background dan main container
            StackPane stackPane = new StackPane();
            stackPane.getChildren().addAll(dotBackground, mainContainer);

            view.setCenter(stackPane);

        } catch (Exception e) {
            // Fallback background beige
            view.setStyle("-fx-background-color: #F5E6A3;");
            System.err.println("Gagal memuat dot background: " + e.getMessage());
        }
    }

    private VBox createContentContainer() {
        VBox container = new VBox(30);
        container.setAlignment(Pos.TOP_CENTER);
        container.setPadding(new Insets(40, 50, 40, 50));
        container.setStyle("-fx-background-color: transparent;");
        container.setMinHeight(700); // Minimum height untuk scroll

        // Header dengan gambar "Cocokkan Gambar"
        VBox headerSection = new VBox(20);
        headerSection.setAlignment(Pos.CENTER);

        try {
            ImageView headerImage = new ImageView(new Image(getClass().getResourceAsStream("/images/Cocokkan Gambar.png")));
            headerImage.setFitHeight(60);
            headerImage.setPreserveRatio(true);
            headerSection.getChildren().add(headerImage);
        } catch (Exception e) {
            Label headerLabel = new Label("Mencocokkan Gambar");
            headerLabel.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 28px; -fx-font-weight: bold; -fx-text-fill: #516BB0;");
            headerSection.getChildren().add(headerLabel);
        }

        // Instruksi
        Label instruksiLabel = new Label("Hubungkan gambar dengan jawaban yang tepat dengan menarik garis dari titik ke titik");
        instruksiLabel.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-text-fill: #1A1E2C; -fx-text-alignment: center;");
        instruksiLabel.setWrapText(true);
        instruksiLabel.setMaxWidth(600);
        headerSection.getChildren().add(instruksiLabel);

        container.getChildren().add(headerSection);
        return container;
    }

    public void setupMatchingGame(List<String> imagePaths, List<String> answerTexts, List<String> imageIds, List<String> correctAnswerIds) {
        this.imagePaths = imagePaths;
        this.answerTexts = answerTexts;
        this.imageIds = imageIds;
        this.correctAnswerIds = correctAnswerIds;

        // Clear previous connections
        connections.clear();
        imageButtons.clear();
        answerButtons.clear();
        connectionLines.clear();

        // Get content container
        VBox contentContainer = (VBox) ((ScrollPane) ((BorderPane) ((StackPane) view.getCenter()).getChildren().get(1)).getCenter()).getContent();

        // Clear previous game content (keep header)
        if (contentContainer.getChildren().size() > 1) {
            contentContainer.getChildren().subList(1, contentContainer.getChildren().size()).clear();
        }

        // Game area dengan line container
        StackPane gameArea = new StackPane();
        gameArea.setPrefHeight(500);
        gameArea.setMaxHeight(500);

        // Line container untuk menggambar garis
        lineContainer = new Pane();
        lineContainer.setPrefSize(1180, 500);
        lineContainer.setStyle("-fx-background-color: transparent;");

        // Main game layout
        HBox gameLayout = new HBox(200); // Increase spacing for better line drawing
        gameLayout.setAlignment(Pos.CENTER);
        gameLayout.setPadding(new Insets(50));

        // Left side - Images
        VBox imageColumn = createImageColumn();

        // Right side - Answers
        VBox answerColumn = createAnswerColumn();

        gameLayout.getChildren().addAll(imageColumn, answerColumn);

        gameArea.getChildren().addAll(gameLayout, lineContainer); // lineContainer on top for proper rendering

        contentContainer.getChildren().add(gameArea);

        // Action buttons
        HBox buttonSection = new HBox(30);
        buttonSection.setAlignment(Pos.CENTER);
        buttonSection.setPadding(new Insets(30, 0, 0, 0));

        Button selesaiButton = new Button("Selesai");
        selesaiButton.setPrefSize(150, 50);
        selesaiButton.setStyle("-fx-background-color: #516BB0; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 600; -fx-background-radius: 15;");
        selesaiButton.setOnAction(e -> checkAnswers());

        kembaliButton = new Button();
        try {
            ImageView backIcon = new ImageView(new Image(getClass().getResourceAsStream("/images/Back.png")));
            backIcon.setFitWidth(40);
            backIcon.setFitHeight(40);
            backIcon.setPreserveRatio(true);
            kembaliButton.setGraphic(backIcon);
        } catch (Exception e) {
            kembaliButton.setText("Kembali");
        }
        kembaliButton.setStyle("-fx-background-color: transparent; -fx-border-width: 0; -fx-padding: 10;");

        buttonSection.getChildren().addAll(kembaliButton, selesaiButton);
        contentContainer.getChildren().add(buttonSection);
    }

    private VBox createImageColumn() {
        VBox imageColumn = new VBox(30);
        imageColumn.setAlignment(Pos.CENTER_LEFT);
        imageColumn.setPrefWidth(400);

        Label imageTitle = new Label("Gambar");
        imageTitle.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 20px; -fx-font-weight: bold; -fx-text-fill: #516BB0;");
        imageColumn.getChildren().add(imageTitle);

        for (int i = 0; i < imagePaths.size(); i++) {
            HBox imageRow = createImageRow(imagePaths.get(i), imageIds.get(i));
            imageColumn.getChildren().add(imageRow);
        }

        return imageColumn;
    }

    private HBox createImageRow(String imagePath, String imageId) {
        HBox row = new HBox(15);
        row.setAlignment(Pos.CENTER_LEFT);

        // Image container
        VBox imageContainer = new VBox();
        imageContainer.setAlignment(Pos.CENTER);
        imageContainer.setPrefSize(150, 100);
        imageContainer.setStyle("-fx-background-color: white; -fx-background-radius: 10; -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.2), 8, 0, 0, 3);");

        try {
            ImageView imageView = new ImageView(new Image(getClass().getResourceAsStream(imagePath)));
            imageView.setFitWidth(130);
            imageView.setFitHeight(80);
            imageView.setPreserveRatio(true);
            imageContainer.getChildren().add(imageView);
        } catch (Exception e) {
            Label placeholder = new Label("Gambar");
            placeholder.setStyle("-fx-font-size: 14px; -fx-text-fill: #666;");
            imageContainer.getChildren().add(placeholder);
        }

        // Connection point (dot)
        Button connectPoint = new Button();
        connectPoint.setPrefSize(20, 20);
        connectPoint.setStyle("-fx-background-color: #516BB0; -fx-background-radius: 10; -fx-border-width: 0;");

        try {
            ImageView dotIcon = new ImageView(new Image(getClass().getResourceAsStream("/images/Cocokkan gambar titik.png")));
            dotIcon.setFitWidth(16);
            dotIcon.setFitHeight(16);
            connectPoint.setGraphic(dotIcon);
        } catch (Exception e) {
            connectPoint.setStyle("-fx-background-color: #516BB0; -fx-background-radius: 10; -fx-border-width: 0;");
        }

        connectPoint.setOnAction(e -> startConnection(imageId, connectPoint));

        imageButtons.put(imageId, connectPoint);
        row.getChildren().addAll(imageContainer, connectPoint);
        return row;
    }

    private VBox createAnswerColumn() {
        VBox answerColumn = new VBox(30);
        answerColumn.setAlignment(Pos.CENTER_RIGHT);
        answerColumn.setPrefWidth(400);

        Label answerTitle = new Label("Jawaban");
        answerTitle.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 20px; -fx-font-weight: bold; -fx-text-fill: #516BB0;");
        answerColumn.getChildren().add(answerTitle);

        for (int i = 0; i < answerTexts.size(); i++) {
            HBox answerRow = createAnswerRow(answerTexts.get(i), imageIds.get(i));
            answerColumn.getChildren().add(answerRow);
        }

        return answerColumn;
    }

    private HBox createAnswerRow(String answerText, String answerId) {
        HBox row = new HBox(15);
        row.setAlignment(Pos.CENTER_RIGHT);

        // Connection point (dot)
        Button connectPoint = new Button();
        connectPoint.setPrefSize(20, 20);
        connectPoint.setStyle("-fx-background-color: #F5E6A3; -fx-background-radius: 10; -fx-border-width: 0;");

        try {
            ImageView dotIcon = new ImageView(new Image(getClass().getResourceAsStream("/images/Cocokkan gambar titik.png")));
            dotIcon.setFitWidth(16);
            dotIcon.setFitHeight(16);
            connectPoint.setGraphic(dotIcon);
        } catch (Exception e) {
            connectPoint.setStyle("-fx-background-color: #F5E6A3; -fx-background-radius: 10; -fx-border-width: 0;");
        }

        connectPoint.setOnAction(e -> completeConnection(answerId, connectPoint));

        // Answer container
        VBox answerContainer = new VBox();
        answerContainer.setAlignment(Pos.CENTER);
        answerContainer.setPrefSize(150, 100);
        answerContainer.setStyle("-fx-background-color: white; -fx-background-radius: 10; -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.2), 8, 0, 0, 3);");

        Label answerLabel = new Label(answerText);
        answerLabel.setStyle("-fx-font-family: 'Poppins', Arial; -fx-font-size: 14px; -fx-font-weight: 600; -fx-text-fill: #1A1E2C; -fx-text-alignment: center;");
        answerLabel.setWrapText(true);
        answerLabel.setMaxWidth(130);
        answerContainer.getChildren().add(answerLabel);

        answerButtons.put(answerId, connectPoint);
        row.getChildren().addAll(connectPoint, answerContainer);
        return row;
    }

    private void startConnection(String imageId, Button imageButton) {
        // Clear previous selection
        resetAllButtonStyles();

        selectedImageId = imageId;

        // Visual feedback - highlight selected image point
        imageButton.setStyle("-fx-background-color: #2ecc71; -fx-background-radius: 10; -fx-border-width: 0;");

        // If there was a previous connection from this image, highlight the connected answer
        String connectedAnswerId = connections.get(imageId);
        if (connectedAnswerId != null) {
            Button answerButton = answerButtons.get(connectedAnswerId);
            answerButton.setStyle("-fx-background-color: #e74c3c; -fx-background-radius: 10; -fx-border-width: 0;");
        }
    }

    private void completeConnection(String answerId, Button answerButton) {
        if (selectedImageId != null) {
            // Remove old connection if exists
            String oldAnswer = connections.get(selectedImageId);
            if (oldAnswer != null) {
                Line oldLine = connectionLines.get(selectedImageId);
                if (oldLine != null) {
                    lineContainer.getChildren().remove(oldLine);
                }
            }

            // Create new connection
            Button imageButton = imageButtons.get(selectedImageId);
            Line line = createConnectionLine(imageButton, answerButton);

            lineContainer.getChildren().add(line);
            connections.put(selectedImageId, answerId);
            connectionLines.put(selectedImageId, line);

            // Reset visual feedback
            resetAllButtonStyles();
            selectedImageId = null;
        }
    }

    private Line createConnectionLine(Button startButton, Button endButton) {
        Line line = new Line();

        // Calculate positions based on scene coordinates
        double startX = startButton.getLayoutX() + startButton.getWidth() / 2;
        double startY = startButton.getLayoutY() + startButton.getHeight() / 2;
        double endX = endButton.getLayoutX() + endButton.getWidth() / 2;
        double endY = endButton.getLayoutY() + endButton.getHeight() / 2;

        // Adjust for the game layout positioning
        line.setStartX(startX + 50); // Adjust for padding
        line.setStartY(startY + 50);
        line.setEndX(endX + 50);
        line.setEndY(endY + 50);

        line.setStroke(Color.web("#516BB0"));
        line.setStrokeWidth(3);
        line.setOpacity(0.8);

        return line;
    }

    private void resetAllButtonStyles() {
        // Reset image buttons
        for (Button button : imageButtons.values()) {
            button.setStyle("-fx-background-color: #516BB0; -fx-background-radius: 10; -fx-border-width: 0;");
        }

        // Reset answer buttons
        for (Button button : answerButtons.values()) {
            button.setStyle("-fx-background-color: #F5E6A3; -fx-background-radius: 10; -fx-border-width: 0;");
        }
    }

    private void checkAnswers() {
        int correctAnswers = 0;

        // Count correct answers
        for (int i = 0; i < imageIds.size(); i++) {
            String imageId = imageIds.get(i);
            String userAnswer = connections.get(imageId);
            String correctAnswer = correctAnswerIds.get(i);

            if (userAnswer != null && userAnswer.equals(correctAnswer)) {
                correctAnswers++;
            }
        }

        // Trigger callback with results
        if (onGameComplete != null) {
            onGameComplete.onGameComplete(correctAnswers, imageIds.size());
        }
    }

    /**
     * Membuat navbar seperti halaman lain
     */
    private HBox createNavbar() {
        HBox navbar = new HBox();
        navbar.setPrefHeight(80);
        navbar.setPadding(new Insets(15, 40, 15, 40));
        navbar.setAlignment(Pos.CENTER_LEFT);
        navbar.setStyle("-fx-background-color: #516BB0;");

        // Logo SportEdu di kiri
        try {
            ImageView logo = new ImageView(new Image(getClass().getResourceAsStream("/images/logo.png")));
            logo.setFitHeight(50);
            logo.setPreserveRatio(true);

            HBox logoContainer = new HBox();
            logoContainer.setAlignment(Pos.CENTER_LEFT);
            logoContainer.getChildren().add(logo);
            navbar.getChildren().add(logoContainer);
        } catch (Exception e) {
            HBox logoContainer = new HBox();
            navbar.getChildren().add(logoContainer);
        }

        // Spacer
        HBox spacer = new HBox();
        HBox.setHgrow(spacer, javafx.scene.layout.Priority.ALWAYS);
        navbar.getChildren().add(spacer);

        // Tombol navigasi
        HBox navButtons = new HBox(30);
        navButtons.setAlignment(Pos.CENTER_RIGHT);

        navHomeButton = new Button("Halaman Utama");
        navHomeButton.setStyle("-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;");
        navHomeButton.setOnMouseEntered(e -> navHomeButton.setStyle("-fx-background-color: transparent; -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));
        navHomeButton.setOnMouseExited(e -> navHomeButton.setStyle("-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));

        navMateriButton = new Button("Materi");
        navMateriButton.setStyle("-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;");
        navMateriButton.setOnMouseEntered(e -> navMateriButton.setStyle("-fx-background-color: transparent; -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));
        navMateriButton.setOnMouseExited(e -> navMateriButton.setStyle("-fx-background-color: transparent; -fx-text-fill: white; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 500; -fx-border-width: 0; -fx-padding: 8 16;"));

        navQuizButton = new Button("Quiz");
        navQuizButton.setStyle("-fx-background-color: rgba(245, 230, 163, 0.2); -fx-text-fill: #F5E6A3; -fx-font-family: 'Poppins', Arial; -fx-font-size: 16px; -fx-font-weight: 600; -fx-border-width: 0; -fx-padding: 8 16; -fx-background-radius: 5;");

        navButtons.getChildren().addAll(navHomeButton, navMateriButton, navQuizButton);
        navbar.getChildren().add(navButtons);

        return navbar;
    }

    // Getter methods
    public Parent getView() {
        return view;
    }

    public Button getKembaliButton() {
        return kembaliButton;
    }

    public void setOnGameComplete(OnGameCompleteListener listener) {
        this.onGameComplete = listener;
    }
}

